    expect(response.body.author?.id).toBeDefined();
    expect(Array.isArray(response.body.tags)).toBe(true);
    const editor = response.body.editor;
    expect(editor?.id ?? editor).toBeTruthy();
    expect(editor?.email).toBeUndefined();
